// Real Rust command payloads through the Tauri adapter and every Build 14 read operation.
// The payloads come from src/test/fixtures/command-wire.json, generated by
// src-tauri/src/wire_contract.rs for a fresh journal and for the v3/v4 journals after upgrade.
// A Rust change the frontend would reject fails here. Native IPC itself is not exercised.
import type { JournalRepository } from "@fundedflow/domain";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { createTauriRepository } from "../../lib/data/tauri-repository";
import { readAccountHistory, readAccountLineage, readAccounts, readDeletionPreview } from "../accounts/api/accounts";
import { readImportHistory, readImportProblemRows } from "../imports/api/imports";
import { readLatestSnapshot, readSnapshots } from "../insights/api/snapshots";
import { readJournal } from "../journal/api/journal";
import { readLedger, readLedgerBalance } from "../ledger/api/ledger";
import { readSettings } from "../settings/api/settings";
import { readTrades } from "../trades/api/trades";
import wire from "../../test/fixtures/command-wire.json";

type PerAccount = {
  accountId: string; history: unknown; lineage: unknown; deletionPreview: unknown; trades: unknown[]; journal: unknown[];
  imports: { id: string }[]; problemRows: { batchId: string; rows: unknown[] }[]; ledger: unknown[]; balanceAdjustment: string;
  snapshots: unknown[]; latestSnapshot: unknown;
};
type Journal = { accounts: { id: string }[]; perAccount: PerAccount[]; settings: unknown[] };
const fixture = wire as unknown as { journals: Record<string, Journal> };

const adapter = vi.hoisted(() => ({ current: null as unknown as JournalRepository }));
vi.mock("../../lib/data/api", () => ({ get repository() { return adapter.current; } }));

function answer(journal: Journal) {
  const per = (id: unknown) => {
    const found = journal.perAccount.find(p => p.accountId === id);
    if (!found) throw { kind: "notFound", message: "no account" };
    return found;
  };
  return async (command: string, args: Record<string, unknown> = {}) => {
    const id = args.id ?? args.accountId;
    switch (command) {
      case "list_accounts": return journal.accounts;
      case "get_account": {
        const account = journal.accounts.find(a => a.id === id);
        if (!account) throw { kind: "notFound", message: "no account" };
        return account;
      }
      case "get_account_history": return per(id).history;
      case "get_account_lineage": return per(id).lineage;
      case "preview_account_deletion": return per(id).deletionPreview;
      case "list_trades": return per(id).trades;
      case "list_journal_entries": return per(id).journal;
      case "list_csv_imports": return per(id).imports;
      case "list_csv_import_problem_rows": return journal.perAccount.flatMap(p => p.problemRows).find(r => r.batchId === args.batchId)?.rows ?? [];
      case "list_ledger_entries": return per(id).ledger;
      case "get_ledger_balance_adjustment": return per(id).balanceAdjustment;
      case "list_account_snapshots": return per(id).snapshots;
      case "get_latest_account_snapshot": return per(id).latestSnapshot;
      case "list_settings": return journal.settings;
      default: throw new Error(`unexpected command ${command}`);
    }
  };
}

describe.each(Object.entries(fixture.journals))("Rust payloads from the %s journal", (_name, journal) => {
  beforeEach(() => {
    adapter.current = createTauriRepository(answer(journal) as never);
  });

  it("has data in every collection the frontend models (fresh journal) or real legacy records", () => {
    expect(journal.accounts.length).toBeGreaterThan(0);
    expect(journal.perAccount.some(p => p.trades.length > 0)).toBe(true);
  });

  it("passes accounts, settings and every per-account read through the Build 14 operations", async () => {
    const accounts = (await readAccounts("all")).value;
    expect(accounts.map(a => a.id).sort()).toEqual(journal.accounts.map(a => a.id).sort());
    await readSettings();
    for (const p of journal.perAccount) {
      const id = p.accountId;
      await readAccountHistory(id);
      await readAccountLineage(id);
      await readDeletionPreview(id);
      const trades = (await readTrades(id)).value;
      expect(trades).toHaveLength(p.trades.length);
      for (const trade of trades) expect(trade.currency).toBe(accounts.find(a => a.id === id)!.currency);
      expect((await readJournal(id)).value).toHaveLength(p.journal.length);
      const imports = (await readImportHistory(id)).value;
      expect(imports).toHaveLength(p.imports.length);
      for (const batch of imports) {
        expect(batch).not.toHaveProperty("errorSummary");
        await readImportProblemRows(id, batch.id);
      }
      expect((await readLedger(id)).value).toHaveLength(p.ledger.length);
      await readLedgerBalance(id);
      const snapshots = (await readSnapshots(id)).value;
      expect(snapshots).toHaveLength(p.snapshots.length);
      for (const snapshot of snapshots) expect(snapshot.currency).toBeNull();
      await readLatestSnapshot(id);
    }
  });
});

it("covers the records a fresh journal can hold", () => {
  const fresh = fixture.journals.fresh;
  const all = fresh.perAccount;
  expect(all.some(p => p.journal.length > 0)).toBe(true);
  expect(all.some(p => p.problemRows.some(r => r.rows.length > 0))).toBe(true);
  expect(all.some(p => p.ledger.length > 0)).toBe(true);
  expect(all.some(p => p.snapshots.length > 1)).toBe(true);
  expect(all.some(p => (p.lineage as unknown[]).length > 1)).toBe(true);
  expect(fresh.settings.length).toBeGreaterThan(0);
});
